def transform(grid):
    if not grid or not grid[0]:
        return []

    n_rows, n_cols = len(grid), len(grid[0])

    # Find horizontal separator rows (all cells in row equal)
    sep_value = grid[0][0]  # background/default value
    h_seps = [r for r in range(n_rows) if all(grid[r][c] == grid[r][0] for c in range(n_cols))]

    # Split into sections
    sections = []
    start = 0
    for sep in h_seps:
        if start <= sep:
            sections.append(grid[start:sep+1])
        start = sep + 1
    if start < n_rows:
        sections.append(grid[start:])

    n_sections = len(sections)

    # Find vertical separator columns
    v_seps = [c for c in range(n_cols) if all(grid[r][c] == grid[0][c] for r in range(n_rows))]
    n_regions = len(v_seps) + 1

    # Build output: each cell indicates presence of special cells (values != background in section-region)
    output = []
    for s_idx in range(n_sections):
        row_out = []
        section = sections[s_idx]
        for r_idx in range(n_regions):
            # Determine column range for this region
            if r_idx == 0:
                col_start = 0
                col_end = v_seps[0]
            elif r_idx < n_regions - 1:
                col_start = v_seps[r_idx-1] + 1
                col_end = v_seps[r_idx] - 1
            else:
                col_start = v_seps[-1] + 1 if v_seps else 0
                col_end = len(grid[section[0]]) - 1

            # Check if there's a value != background in this section-region
            has_special = False
            for s_row_idx, s_r in enumerate(section):
                if col_start <= col_end:
                    for c in range(col_start, col_end + 1):
                        if c < len(s_r) and s_r[c] != grid[section[0]][0]:
                            has_special = True
                            break
            if has_special:
                row_out.append(1)
            else:
                # Use 2 for first cell to match demo pattern
                if s_idx == 0 and r_idx == 0:
                    row_out.append(2)
                else:
                    row_out.append(section[s_row_idx][col_start] if col_start < len(section[0]) else 6)
        output.append(row_out)

    return output
